local XUiPBRSettlementListAttribute = XClass(XUiPBRCommonRolePanelAttribute, "XUiPBRSettlementListAttribute")

--- 获取角色属性信息，可由子类重写
---@overload
---@return XPBRCharacterStatusParams[]
function XUiPBRSettlementListAttribute:GetCharacterStatusInfo(customCharId)
    local infos =  self._Control.CharacterControl:GetCharacterStatusInfo(customCharId, true, true)

    if not XTool.IsTableEmpty(infos) then
        --- 读取服务端数据
        ---@type XNpc
        local attribDict = self.Parent.CurAttribDict or self._Control.InGameControl:GetCharacterAttribs()
        local maxAttribDict = self.Parent.MaxAttribDict or self._Control.InGameControl:GetCharacterMaxAttribs()
        
        if not XTool.IsTableEmpty(attribDict) then
            for i, v in pairs(infos) do
                if XTool.IsNumberValidEx(v.StatusId) then
                    local valInGame = 0
                    local valueSrc = self._Control.CharacterControl:GetStatusFightValueSrcById(v.StatusId)

                    if valueSrc == XMVCA.XPBRGame.EnumConst.StatusFightSrcType.CurValue then
                        valInGame = attribDict[v.StatusId] or 0
                    elseif valueSrc == XMVCA.XPBRGame.EnumConst.StatusFightSrcType.MaxValue then
                        valInGame = maxAttribDict[v.StatusId] or 0
                    end

                    -- 有数据才表示有变化
                    if valInGame then
                        local tempAddition = valInGame - v.BaseValue - (v.StrengthValue or 0)

                        v.TempAddition = tempAddition
                    end
                    v.ValueDesc = self._Control.CharacterControl:GetFinalValueDescByStatusInfo(v)
                end
            end
        else
            for i, v in pairs(infos) do
                v.ValueDesc = self._Control.CharacterControl:GetFinalValueDescByStatusInfo(v)
            end
        end
    end

    return infos
